import snthIndexOf = require( './index' );


// TESTS //

// The function returns a number...
{
	var x = new Float32Array( [ 1.0, 2.0, 3.0 ] );

	snthIndexOf( x.length, 1, 2.0, x, 1 ); // $ExpectType number
}

// The compiler throws an error if the function is provided a first argument which is not a number...
{
	var x = new Float32Array( [ 1.0, 2.0, 3.0 ] );

	snthIndexOf( '1', 1, 2.0, x, 1 ); // $ExpectError
	snthIndexOf( true, 1, 2.0, x, 1 ); // $ExpectError
	snthIndexOf( false, 1, 2.0, x, 1 ); // $ExpectError
	snthIndexOf( null, 1, 2.0, x, 1 ); // $ExpectError
	snthIndexOf( {}, 1, 2.0, x, 1 ); // $ExpectError
	snthIndexOf( ( x: number ): number => x, 1, 2.0, x, 1 ); // $ExpectError
}

// The compiler throws an error if the function is provided a second argument which is not a number...
{
	var x = new Float32Array( [ 1.0, 2.0, 3.0 ] );

	snthIndexOf( x.length, '1', 2.0, x, 1 ); // $ExpectError
	snthIndexOf( x.length, true, 2.0, x, 1 ); // $ExpectError
	snthIndexOf( x.length, false, 2.0, x, 1 ); // $ExpectError
	snthIndexOf( x.length, null, 2.0, x, 1 ); // $ExpectError
	snthIndexOf( x.length, {}, 2.0, x, 1 ); // $ExpectError
	snthIndexOf( x.length, ( x: number ): number => x, 2.0, x, 1 ); // $ExpectError
}

// The compiler throws an error if the function is provided a third argument which is not a number...
{
	var x = new Float32Array( [ 1.0, 2.0, 3.0 ] );

	snthIndexOf( x.length, 1, '1', x, 1 ); // $ExpectError
	snthIndexOf( x.length, 1, true, x, 1 ); // $ExpectError
	snthIndexOf( x.length, 1, false, x, 1 ); // $ExpectError
	snthIndexOf( x.length, 1, null, x, 1 ); // $ExpectError
	snthIndexOf( x.length, 1, {}, x, 1 ); // $ExpectError
	snthIndexOf( x.length, 1, ( x: number ): number => x, x, 1 ); // $ExpectError
}

// The compiler throws an error if the function is provided a fourth argument which is not a Float32Array...
{
	snthIndexOf( x.length, 1, 1.0, '1', 1 ); // $ExpectError
	snthIndexOf( x.length, 1, 1.0, true, 1 ); // $ExpectError
	snthIndexOf( x.length, 1, 1.0, false, 1 ); // $ExpectError
	snthIndexOf( x.length, 1, 1.0, null, 1 ); // $ExpectError
	snthIndexOf( x.length, 1, 1.0, {}, 1 ); // $ExpectError
	snthIndexOf( x.length, 1, 1.0, ( x: number ): number => x, 1 ); // $ExpectError
}

// The compiler throws an error if the function is provided a fifth argument which is not a number...
{
	var x = new Float32Array( [ 1.0, 2.0, 3.0 ] );

	snthIndexOf( x.length, 1, 2.0, x, '1' ); // $ExpectError
	snthIndexOf( x.length, 1, 2.0, x, true ); // $ExpectError
	snthIndexOf( x.length, 1, 2.0, x, false ); // $ExpectError
	snthIndexOf( x.length, 1, 2.0, x, null ); // $ExpectError
	snthIndexOf( x.length, 1, 2.0, x, {} ); // $ExpectError
	snthIndexOf( x.length, 1, 2.0, x, ( x: number ): number => x ); // $ExpectError
}

// The compiler throws an error if the function is provided an unsupported number of arguments...
{
	snthIndexOf(); // $ExpectError
	snthIndexOf( 3, 1 ); // $ExpectError
	snthIndexOf( 3, 1, 2.0 ); // $ExpectError
	snthIndexOf( 3, 1, 2.0, new Float32Array( [ 1.0, 2.0, 3.0 ] ) ); // $ExpectError
	snthIndexOf( 3, 1, 2.0, new Float32Array( [ 1.0, 2.0, 3.0 ] ), 1, {} ); // $ExpectError
}

// Attached to main export is an `ndarray` method which returns a number...
{
	var x = new Float32Array( [ 1.0, 2.0, 3.0 ] );

	snthIndexOf.ndarray( x.length, 1, 2.0, x, 1, 0 ); // $ExpectType number
}

// The compiler throws an error if the `ndarray` method is provided a first argument which is not a number...
{
	var x = new Float32Array( [ 1.0, 2.0, 3.0 ] );

	snthIndexOf.ndarray( '1', 1, 2.0, x, 1, 1 ); // $ExpectError
	snthIndexOf.ndarray( true, 1, 2.0, x, 1, 1 ); // $ExpectError
	snthIndexOf.ndarray( false, 1, 2.0, x, 1, 1 ); // $ExpectError
	snthIndexOf.ndarray( null, 1, 2.0, x, 1, 1 ); // $ExpectError
	snthIndexOf.ndarray( {}, 1, 2.0, x, 1, 1 ); // $ExpectError
	snthIndexOf.ndarray( ( x: number ): number => x, 1, 2.0, x, 1, 1 ); // $ExpectError
}

// The compiler throws an error if the `ndarray` method is provided a second argument which is not a number...
{
	var x = new Float32Array( [ 1.0, 2.0, 3.0 ] );

	snthIndexOf.ndarray( x.length, '1', 2.0, x, 1, 1 ); // $ExpectError
	snthIndexOf.ndarray( x.length, true, 2.0, x, 1, 1 ); // $ExpectError
	snthIndexOf.ndarray( x.length, false, 2.0, x, 1, 1 ); // $ExpectError
	snthIndexOf.ndarray( x.length, null, 2.0, x, 1, 1 ); // $ExpectError
	snthIndexOf.ndarray( x.length, {}, 2.0, x, 1, 1 ); // $ExpectError
	snthIndexOf.ndarray( x.length, ( x: number ): number => x, 2.0, x, 1, 1 ); // $ExpectError
}

// The compiler throws an error if the `ndarray` method is provided a third argument which is not a number...
{
	var x = new Float32Array( [ 1.0, 2.0, 3.0 ] );

	snthIndexOf.ndarray( x.length, 1, '1', x, 1, 1 ); // $ExpectError
	snthIndexOf.ndarray( x.length, 1, true, x, 1, 1 ); // $ExpectError
	snthIndexOf.ndarray( x.length, 1, false, x, 1, 1 ); // $ExpectError
	snthIndexOf.ndarray( x.length, 1, null, x, 1, 1 ); // $ExpectError
	snthIndexOf.ndarray( x.length, 1, {}, x, 1, 1 ); // $ExpectError
	snthIndexOf.ndarray( x.length, 1, ( x: number ): number => x, x, 1, 1 ); // $ExpectError
}

// The compiler throws an error if the `ndarray` method is provided a fourth argument which is not a Float32Array...
{
	snthIndexOf.ndarray( x.length, 1, 1.0, '1', 1, 1 ); // $ExpectError
	snthIndexOf.ndarray( x.length, 1, 1.0, true, 1, 1 ); // $ExpectError
	snthIndexOf.ndarray( x.length, 1, 1.0, false, 1, 1 ); // $ExpectError
	snthIndexOf.ndarray( x.length, 1, 1.0, null, 1, 1 ); // $ExpectError
	snthIndexOf.ndarray( x.length, 1, 1.0, {}, 1, 1 ); // $ExpectError
	snthIndexOf.ndarray( x.length, 1, 1.0, ( x: number ): number => x, 1, 1 ); // $ExpectError
}

// The compiler throws an error if the `ndarray` method is provided a fifth argument which is not a number...
{
	var x = new Float32Array( [ 1.0, 2.0, 3.0 ] );

	snthIndexOf.ndarray( x.length, 1, 2.0, x, '1', 1 ); // $ExpectError
	snthIndexOf.ndarray( x.length, 1, 2.0, x, true, 1 ); // $ExpectError
	snthIndexOf.ndarray( x.length, 1, 2.0, x, false, 1 ); // $ExpectError
	snthIndexOf.ndarray( x.length, 1, 2.0, x, null, 1 ); // $ExpectError
	snthIndexOf.ndarray( x.length, 1, 2.0, x, {}, 1 ); // $ExpectError
	snthIndexOf.ndarray( x.length, 1, 2.0, x, ( x: number ): number => x, 1 ); // $ExpectError
}

// The compiler throws an error if the `ndarray` method is provided a sixth argument which is not a number...
{
	var x = new Float32Array( [ 1.0, 2.0, 3.0 ] );

	snthIndexOf.ndarray( x.length, 1, 2.0, x, 1, '1' ); // $ExpectError
	snthIndexOf.ndarray( x.length, 1, 2.0, x, 1, true ); // $ExpectError
	snthIndexOf.ndarray( x.length, 1, 2.0, x, 1, false ); // $ExpectError
	snthIndexOf.ndarray( x.length, 1, 2.0, x, 1, null ); // $ExpectError
	snthIndexOf.ndarray( x.length, 1, 2.0, x, 1, {} ); // $ExpectError
	snthIndexOf.ndarray( x.length, 1, 2.0, x, 1, ( x: number ): number => x ); // $ExpectError
}

// The compiler throws an error if the `ndarray` method is provided an unsupported number of arguments...
{
	snthIndexOf.ndarray(); // $ExpectError
	snthIndexOf.ndarray( 3, 1 ); // $ExpectError
	snthIndexOf.ndarray( 3, 1, 2.0 ); // $ExpectError
	snthIndexOf.ndarray( 3, 1, 2.0, new Float32Array( [ 1.0, 2.0, 3.0 ] ) ); // $ExpectError
	snthIndexOf.ndarray( 3, 1, 2.0, new Float32Array( [ 1.0, 2.0, 3.0 ] ), 1 ); // $ExpectError
	snthIndexOf.ndarray( 3, 1, 2.0, new Float32Array( [ 1.0, 2.0, 3.0 ] ), 1, 0, {} ); // $ExpectError
}
